class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self._options: dict[str, int] = {}
        self._voters: set[str] = set()

    def add_option(self, option: str) -> None:
        if option not in self._options:
            self._options[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if voter in self._voters:
            raise ValueError(f"Voter '{voter}' has already voted.")
        if option not in self._options:
            raise ValueError(f"Option '{option}' does not exist.")
        self._voters.add(voter)
        self._options[option] += 1

    def winner(self) -> str | None:
        if not self._options:
            return None

        # Determine the option with the most votes.
        # In case of a tie, the tied option that was added last wins.
        # Iterating in reverse preserves the insertion order in reverse,
        # so using `>` for strictly greater ensures that the first encountered
        # maximum from the end (i.e. added last) is retained.
        best_option = None
        max_votes = -1

        for option, votes in reversed(self._options.items()):
            if votes > max_votes:
                max_votes = votes
                best_option = option

        return best_option
